        return false;
    }
    size_t pixels = (size_t)decoded.width * (size_t)decoded.height;
    if (pixels > SVG_SHAPE_MEDIA_MAX_IMAGE_PIXELS -
                 builder->decoded_image_pixels) {
        builder->media->release_image(builder->media->context, &decoded);
        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_LIMIT, href.offset);
        return false;
    }
    builder->decoded_image_pixels += pixels;
    image.rgba = decoded.rgba;
    image.byte_count = decoded.byte_count;
    image.row_stride = decoded.row_stride;
    image.pixel_width = decoded.width;
    image.pixel_height = decoded.height;
    image.owner = decoded.owner;

    svg_shape_aspect aspect = {.align_x = 0.5, .align_y = 0.5, .set = true};
    svg_xml_span aspect_span;
    if (attribute(source, tokens, context->token_count, element,
                  "preserveAspectRatio", NULL, &aspect_span) &&
        !svg_shape_parse_preserve_aspect(source, aspect_span, &aspect)) {
        decoded.owner = image.owner;
        builder->media->release_image(builder->media->context, &decoded);
        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_UNSUPPORTED,
                       aspect_span.offset);
        return false;
    }
    if (!aspect.none) {
        double sx = image.width / (double)image.pixel_width;
        double sy = image.height / (double)image.pixel_height;
        double scale = aspect.slice ? fmax(sx, sy) : fmin(sx, sy);
        image.draw_width = (double)image.pixel_width * scale;
        image.draw_height = (double)image.pixel_height * scale;
        image.draw_x = image.x +
            (image.width - image.draw_width) * aspect.align_x;
        image.draw_y = image.y +
            (image.height - image.draw_height) * aspect.align_y;
    }
    builder->doc->images[builder->shape_index] = image;
    if (!svg_shape_ensure_fill_paint(builder, builder->shape_index,
            tokens[element].name.offset)) return false;
    svg_shape_paint *paint = svg_shape_paint_for_shape_mutable(
        builder->doc, builder->shape_index);
    if (paint == NULL) return false;
    paint->kind = SVG_SHAPE_PAINT_IMAGE;
    return true;
}

bool svg_shape_builder_add_image_element(
    svg_shape_builder *builder, base_bytes source, svg_xml_token *tokens,
    size_t token_count, size_t element, const svg_css_paint *style,
    geom_affine transform)
{
    image_geometry_context context = {source, tokens, token_count, element};
    if (!svg_shape_builder_add_custom_element(
            builder, source, tokens, token_count, element, style, transform,
            image_geometry, &context)) return false;
    size_t shape = builder->shape_index;
    size_t first = builder->doc->shape_edge_start[shape];
    size_t count = builder->doc->shape_edge_count[shape];
    for (size_t i = first; i < first + count; ++i)
        builder->doc->colors[i * 4U + 3U] = 0U;
    return true;
}
#include "shape_internal.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

#define TEXT_CACHE_ENTRIES 32U
#define TEXT_CACHE_BYTES (256U * 1024U)
#define TEXT_CACHE_COMMANDS SVG_SHAPE_MEDIA_MAX_PATH_COMMANDS

typedef struct text_cache_entry {
    uint8_t *text;
    size_t text_length;
    svg_shape_text_family *families;
    size_t family_count;
    double size_points;
    double weight;
    double letter_spacing_points;
    svg_shape_text_style style;
    svg_shape_text_layout layout;
} text_cache_entry;

struct svg_shape_text_cache {
    const svg_shape_media_providers *providers;
    text_cache_entry entries[TEXT_CACHE_ENTRIES];
    size_t count;
    size_t bytes;
    size_t commands;
};

void svg_shape_text_layout_release(const svg_shape_media_providers *providers,
                                    svg_shape_text_layout *layout)
{
    if (providers->release_text != NULL)
        providers->release_text(providers->context, layout);
    else {
        free(layout->glyphs);
        free(layout->commands);
        *layout = (svg_shape_text_layout){0};
    }
}

svg_shape_text_cache *svg_shape_text_cache_create(
    const svg_shape_media_providers *providers)
{
    if (providers == NULL || providers->layout_text == NULL) return NULL;
    svg_shape_text_cache *cache = svg_shape_calloc(1U, sizeof(*cache));
    if (cache != NULL) cache->providers = providers;
    return cache;
}

void svg_shape_text_cache_destroy(svg_shape_text_cache *cache)
{
    if (cache == NULL) return;
    for (size_t i = 0U; i < cache->count; ++i) {
        svg_shape_text_layout_release(cache->providers, &cache->entries[i].layout);
        svg_shape_free(cache->entries[i].text);
        svg_shape_free(cache->entries[i].families);
    }
    svg_shape_free(cache);
}

static bool request_matches(const text_cache_entry *entry,
                            const svg_shape_text_request *request)
{
    if (entry->text_length != request->text.len ||
        entry->family_count != request->font_family_count ||
        entry->size_points != request->size_points ||
        entry->weight != request->weight ||
        entry->style != request->style ||
        entry->letter_spacing_points != request->letter_spacing_points ||
        memcmp(entry->text, request->text.ptr, request->text.len) != 0)
        return false;
    for (size_t i = 0U; i < entry->family_count; ++i) {
        const svg_shape_text_family *a = &entry->families[i];
        const svg_shape_text_family *b = &request->font_families[i];
        if (a->length != b->length || memcmp(a->bytes, b->bytes, a->length) != 0)
            return false;
    }
    return true;
}

bool svg_shape_text_layout_run(svg_shape_text_cache *cache,
                        const svg_shape_text_request *request,
                        svg_shape_text_layout *out, bool *cached,
                        svg_shape_diagnostic *diagnostic,
                        size_t error_offset)
{
    *out = (svg_shape_text_layout){0};
    *cached = false;
    if (cache == NULL || cache->providers->layout_text == NULL ||
        cache->providers->release_text == NULL) {
        svg_shape_fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, error_offset);
        return false;
    }
    for (size_t i = 0U; i < cache->count; ++i) {
        if (request_matches(&cache->entries[i], request)) {
            *out = cache->entries[i].layout;
            *cached = true;
            return true;
        }
    }
    svg_shape_media_status status = cache->providers->layout_text(
        cache->providers->context, request, out);
    if (status != SVG_SHAPE_MEDIA_OK) {
        svg_shape_error error = status == SVG_SHAPE_MEDIA_LIMIT ?
            SVG_SHAPE_ERROR_LIMIT : status == SVG_SHAPE_MEDIA_OOM ?
            SVG_SHAPE_ERROR_OOM : SVG_SHAPE_ERROR_UNSUPPORTED;
        svg_shape_fail(diagnostic, error, error_offset);
        return false;
    }
    if (out->glyph_count > SVG_SHAPE_MEDIA_MAX_GLYPHS ||
        out->command_count > SVG_SHAPE_MEDIA_MAX_PATH_COMMANDS ||
        (out->glyph_count != 0U && out->glyphs == NULL) ||
        (out->command_count != 0U && out->commands == NULL) ||
        !isfinite(out->advance_width)) {
        svg_shape_text_layout_release(cache->providers, out);
        svg_shape_fail(diagnostic, SVG_SHAPE_ERROR_LIMIT, error_offset);
        return false;
    }
    for (size_t i = 0U; i < out->glyph_count; ++i) {
        const svg_shape_text_glyph *glyph = &out->glyphs[i];
        if (!isfinite(glyph->x) || !isfinite(glyph->y) ||
            !isfinite(glyph->advance) || glyph->command_start > out->command_count ||
            glyph->command_count > out->command_count - glyph->command_start) {
            svg_shape_text_layout_release(cache->providers, out);
            svg_shape_fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
                           error_offset);
            return false;
        }
    }
    for (size_t i = 0U; i < out->command_count; ++i) {
        const svg_shape_text_command *command = &out->commands[i];
        if ((unsigned)command->verb > (unsigned)SVG_SHAPE_TEXT_CLOSE) {
            svg_shape_text_layout_release(cache->providers, out);
            svg_shape_fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
                           error_offset);
            return false;
        }
        for (size_t value = 0U; value < 6U; ++value) {
            if (!isfinite(command->values[value])) {
                svg_shape_text_layout_release(cache->providers, out);
                svg_shape_fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
                               error_offset);
                return false;
            }
        }
    }
    if (cache->count < TEXT_CACHE_ENTRIES &&
        request->text.len <= TEXT_CACHE_BYTES - cache->bytes &&
        out->command_count <= TEXT_CACHE_COMMANDS - cache->commands &&
        request->font_family_count <= SVG_SHAPE_MEDIA_MAX_FAMILIES) {
        uint8_t *key_text = svg_shape_malloc(request->text.len == 0U ? 1U :
                                              request->text.len);
        svg_shape_text_family *families = request->font_family_count == 0U ?
            NULL : svg_shape_malloc(request->font_family_count * sizeof(*families));
        if (key_text != NULL &&
            (request->font_family_count == 0U || families != NULL)) {
            if (request->text.len != 0U)
                memcpy(key_text, request->text.ptr, request->text.len);
            if (families != NULL)
                memcpy(families, request->font_families,
                       request->font_family_count * sizeof(*families));
            cache->entries[cache->count] = (text_cache_entry){
                .text = key_text,
                .text_length = request->text.len,
                .families = families,
                .family_count = request->font_family_count,
                .size_points = request->size_points,
                .weight = request->weight,
                .letter_spacing_points = request->letter_spacing_points,
                .style = request->style,
                .layout = *out
            };
            cache->count++;
            cache->bytes += request->text.len;
            cache->commands += out->command_count;
            *cached = true;
        } else {
            svg_shape_free(key_text);
            svg_shape_free(families);
        }
    }
    return true;
}

#include "shape_internal.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

typedef struct outline_context {
    const svg_shape_text_layout *layout;
    const double *x_values;
    size_t x_count;
    const double *y_values;
    size_t y_count;
    const double *dx_values;
    size_t dx_count;
    const double *dy_values;
    size_t dy_count;
    double start_x;
    double start_y;
    double anchor_offset;
    double unit_scale;
    double word_spacing;
    const uint8_t *text;
    size_t text_length;
} outline_context;

static bool text_span_equal(base_bytes source, svg_xml_span span,
                            const char *literal)
{
    size_t length = 0U;
    while (literal[length] != '\0') length++;
    return span.offset <= source.len && span.length == length &&
           length <= source.len - span.offset &&
           memcmp(source.ptr + span.offset, literal, length) == 0;
}

static bool text_attribute(base_bytes source, const svg_xml_token *tokens,
                           size_t count, size_t element, const char *local,
                           const char *prefix, svg_xml_span *out)
{
    for (size_t i = element + 1U;
         i < count && tokens[i].kind == SVG_XML_TOKEN_ATTRIBUTE; ++i) {
        if (!text_span_equal(source, tokens[i].local_name, local)) continue;
        if ((prefix == NULL && tokens[i].prefix.length == 0U) ||
            (prefix != NULL && text_span_equal(source, tokens[i].prefix,
                                                prefix))) {
            *out = tokens[i].value;
            return true;
        }
    }
    return false;
}

static bool normalize_text(base_bytes source, svg_xml_span raw,
                           bool preserve, svg_shape_text_state *state,
                           uint8_t **out_bytes, size_t *out_length,
                           size_t *error_offset)
{
    *out_bytes = NULL;
    *out_length = 0U;
    if (raw.offset > source.len || raw.length > source.len - raw.offset)
        return false;
    uint8_t *decoded = svg_shape_malloc(raw.length == 0U ? 1U : raw.length);
    if (decoded == NULL) return false;
    size_t decoded_length = 0U;
    size_t decode_error = 0U;
    if (!svg_xml_decode_attribute_value(source, raw, decoded, raw.length,
                                        &decoded_length, &decode_error)) {
        *error_offset = raw.offset + decode_error;
        svg_shape_free(decoded);
        return false;
    }
    if (preserve) {
        if (decoded_length != 0U) state->has_position = true;
        *out_bytes = decoded;
        *out_length = decoded_length;
        return true;
    }
    uint8_t *collapsed = svg_shape_malloc(decoded_length == 0U ? 1U :
                                           decoded_length);
    if (collapsed == NULL) {
        svg_shape_free(decoded);
        return false;
    }
    size_t output = 0U;
    size_t i = 0U;
    while (i < decoded_length) {
        uint8_t byte = decoded[i];
        bool whitespace = byte == ' ' || byte == '\t' || byte == '\r' ||
                          byte == '\n';
        if (whitespace) {
            if (state->has_position || output != 0U) state->pending_space = true;
            i++;
            continue;
        }
        if (state->pending_space && (state->has_position || output != 0U))
            collapsed[output++] = ' ';
        state->pending_space = false;
        collapsed[output++] = byte;
        state->has_position = true;
        i++;
    }
    svg_shape_free(decoded);
    *out_bytes = collapsed;
    *out_length = output;
    return true;
}

static bool parse_position_list(base_bytes source, svg_xml_span span,
                                double reference, double **out_values,
                                size_t *out_count, size_t *error_offset)
{
    *out_values = NULL;
    *out_count = 0U;
    if (span.length == 0U || span.offset > source.len ||
        span.length > source.len - span.offset) {
        *error_offset = span.offset;
        return false;
    }
    size_t capacity = span.length < SVG_SHAPE_MEDIA_MAX_GLYPHS ?
                      span.length : SVG_SHAPE_MEDIA_MAX_GLYPHS;
    if (capacity == 0U || capacity > SIZE_MAX / sizeof(double)) {
        *error_offset = span.offset;
        return false;
    }
    double *values = svg_shape_malloc(capacity * sizeof(*values));
    if (values == NULL) return false;
    size_t i = 0U, count = 0U;
    bool need_value = true;
    while (i < span.length) {
        while (i < span.length && (source.ptr[span.offset + i] == ' ' ||
               source.ptr[span.offset + i] == '\t' ||
               source.ptr[span.offset + i] == '\r' ||
               source.ptr[span.offset + i] == '\n')) i++;
        if (i == span.length) break;
        if (source.ptr[span.offset + i] == ',') {
            if (need_value) { *error_offset = span.offset + i; goto invalid; }
            need_value = true;
            i++;
            continue;
        }
        size_t start = i;
        while (i < span.length && source.ptr[span.offset + i] != ',' &&
               source.ptr[span.offset + i] != ' ' &&
               source.ptr[span.offset + i] != '\t' &&
               source.ptr[span.offset + i] != '\r' &&
               source.ptr[span.offset + i] != '\n') i++;
        if (count == capacity || start == i ||
            !svg_shape_read_length(source,
                (svg_xml_span){span.offset + start, i - start}, reference,
                &values[count])) {
            *error_offset = span.offset + start;
            goto invalid;
        }
        count++;
        need_value = false;
    }
    if (count == 0U || need_value) {
        *error_offset = span.offset + span.length;
        goto invalid;
    }
    *out_values = values;
    *out_count = count;
    return true;
invalid:
    svg_shape_free(values);
    return false;
}

static bool parse_families(base_bytes source, const svg_css_paint *style,
                           svg_shape_text_family families[
                               SVG_SHAPE_MEDIA_MAX_FAMILIES],
                           size_t *out_count, size_t *error_offset)
{
    *out_count = 0U;
    svg_xml_span span;
    if (!svg_css_paint_value(style, SVG_CSS_FONT_FAMILY, &span)) return true;
    if (span.offset > source.len || span.length > source.len - span.offset) {
        *error_offset = span.offset;
        return false;
    }
    size_t i = span.offset, end = span.offset + span.length;
    while (i < end) {
        while (i < end && (source.ptr[i] == ' ' || source.ptr[i] == '\t' ||
                           source.ptr[i] == '\r' || source.ptr[i] == '\n')) i++;
        if (i == end) break;
        if (*out_count >= SVG_SHAPE_MEDIA_MAX_FAMILIES) {
            *error_offset = i;
            return false;
        }
        size_t start = i, finish;
        uint8_t quote = source.ptr[i] == '\'' || source.ptr[i] == '"' ?
                        source.ptr[i++] : 0U;
        if (quote != 0U) {
            start = i;
            while (i < end && source.ptr[i] != quote) i++;
            if (i == end) { *error_offset = start - 1U; return false; }
            finish = i;
            i++;
        } else {
            while (i < end && source.ptr[i] != ',') i++;
            finish = i;
            while (finish > start &&
                   (source.ptr[finish - 1U] == ' ' ||
                    source.ptr[finish - 1U] == '\t' ||
                    source.ptr[finish - 1U] == '\r' ||
                    source.ptr[finish - 1U] == '\n')) finish--;
        }
        if (finish == start) { *error_offset = start; return false; }
        families[*out_count] = (svg_shape_text_family){
            source.ptr + start, finish - start};
        (*out_count)++;
        while (i < end && source.ptr[i] != ',') {
            if (source.ptr[i] != ' ' && source.ptr[i] != '\t' &&
                source.ptr[i] != '\r' && source.ptr[i] != '\n') {
                *error_offset = i;
                return false;
            }
            i++;
        }
        if (i < end && source.ptr[i] == ',') i++;
    }
    return *out_count != 0U;
}

static bool parse_size(base_bytes source, const svg_css_paint *style,
                       double reference, double *out, size_t *error_offset)
{
    svg_xml_span span;
    *out = 16.0;
    if (!svg_css_paint_value(style, SVG_CSS_FONT_SIZE, &span)) return true;
    if (!svg_shape_read_length(source, span, reference, out) || *out <= 0.0) {
        *error_offset = span.offset;
        return false;
    }
    return true;
}

static bool parse_weight(base_bytes source, const svg_css_paint *style,
                         double *out, size_t *error_offset)
{
    svg_xml_span span;
    *out = 400.0;
    if (!svg_css_paint_value(style, SVG_CSS_FONT_WEIGHT, &span)) return true;
    if (svg_css_keyword_equals(source, span, "normal")) return true;
    if (svg_css_keyword_equals(source, span, "bold")) { *out = 700.0; return true; }
    if (!svg_shape_read_number(source, span, out) || *out < 100.0 ||
        *out > 900.0 || fmod(*out, 100.0) != 0.0) {
        *error_offset = span.offset;
        return false;
    }
    return true;
}

static bool parse_spacing(base_bytes source, const svg_css_paint *style,
                          svg_css_property property, double reference,
                          double *out, size_t *error_offset)
{
    svg_xml_span span;
    *out = 0.0;
    if (!svg_css_paint_value(style, property, &span) ||
        svg_css_keyword_equals(source, span, "normal")) return true;
    if (!svg_shape_read_length(source, span, reference, out)) {
        *error_offset = span.offset;
        return false;
    }
    return true;
}

static bool parse_text_style(base_bytes source, const svg_css_paint *style,
                             double viewport_width,
                             double viewport_height,
                             svg_shape_text_request *request,
                             svg_shape_text_family families[
                                 SVG_SHAPE_MEDIA_MAX_FAMILIES],
                             size_t *family_count, double *word_spacing,
                             bool *anchor_middle, bool *anchor_end,
                             size_t *error_offset)
{
    double font_size = 16.0;
    if (!parse_size(source, style, viewport_height, &font_size, error_offset) ||
        !parse_weight(source, style, &request->weight, error_offset) ||
        !parse_families(source, style, families, family_count, error_offset) ||
        !parse_spacing(source, style, SVG_CSS_LETTER_SPACING,
                       viewport_width, &request->letter_spacing_points,
                       error_offset) ||
        !parse_spacing(source, style, SVG_CSS_WORD_SPACING,
                       viewport_width, word_spacing, error_offset)) return false;
    request->font_families = families;
    request->font_family_count = *family_count;
    request->size_points = font_size * 0.75;
    request->letter_spacing_points *= 0.75;
    request->style = SVG_SHAPE_TEXT_NORMAL;
    svg_xml_span span;
    if (svg_css_paint_value(style, SVG_CSS_FONT_STYLE, &span)) {
        if (svg_css_keyword_equals(source, span, "italic"))
            request->style = SVG_SHAPE_TEXT_ITALIC;
        else if (svg_css_keyword_equals(source, span, "oblique"))
            request->style = SVG_SHAPE_TEXT_OBLIQUE;
        else if (!svg_css_keyword_equals(source, span, "normal")) {
            *error_offset = span.offset;
            return false;
        }
    }
    *anchor_middle = false;
    *anchor_end = false;
    if (svg_css_paint_value(style, SVG_CSS_TEXT_ANCHOR, &span)) {
        if (svg_css_keyword_equals(source, span, "middle"))
            *anchor_middle = true;
        else if (svg_css_keyword_equals(source, span, "end"))
            *anchor_end = true;
        else if (!svg_css_keyword_equals(source, span, "start")) {
            *error_offset = span.offset;
            return false;
        }
    }
    return true;
}

static bool text_geometry(svg_shape_builder *builder, void *opaque)
{
    outline_context *context = opaque;
    const svg_shape_text_layout *layout = context->layout;
    size_t codepoint = 0U;
    double extra_x = 0.0, extra_y = 0.0, word_offset = 0.0;
    for (size_t glyph_index = 0U; glyph_index < layout->glyph_count;
         ++glyph_index) {
        const svg_shape_text_glyph *glyph = &layout->glyphs[glyph_index];
        bool x_override = glyph_index < context->x_count;
        bool y_override = glyph_index < context->y_count;
        if (glyph_index < context->dx_count) extra_x += context->dx_values[glyph_index];
        if (glyph_index < context->dy_count) extra_y += context->dy_values[glyph_index];
        if (x_override) extra_x = 0.0;
        if (y_override) extra_y = 0.0;
        double gx = (x_override ? context->x_values[glyph_index] :
                     context->start_x + glyph->x * context->unit_scale) + extra_x +
                    context->anchor_offset + word_offset;
        double gy = (y_override ? context->y_values[glyph_index] :
                     context->start_y - glyph->y * context->unit_scale) + extra_y;
        while (codepoint < context->text_length &&
               (context->text[codepoint] & 0xC0U) == 0x80U) codepoint++;
        if (codepoint < context->text_length && context->text[codepoint] == ' ')
            word_offset += context->word_spacing;
        while (codepoint < context->text_length &&
               (context->text[codepoint] & 0xC0U) != 0x80U) codepoint++;
        geom_point current = {0.0, 0.0}, first = {0.0, 0.0};
        bool open = false;
        size_t end = glyph->command_start + glyph->command_count;
        for (size_t index = glyph->command_start; index < end; ++index) {
            const svg_shape_text_command *command = &layout->commands[index];
            if (command->verb == SVG_SHAPE_TEXT_MOVE) {
                if (open && !svg_shape_builder_add_edge(builder, current, first))
                    return false;
                current = (geom_point){gx + command->values[0] * context->unit_scale,
                                       gy - command->values[1] * context->unit_scale};
                first = current;
                open = true;
            } else if (command->verb == SVG_SHAPE_TEXT_LINE) {
                geom_point next = {gx + command->values[0] * context->unit_scale,
                                   gy - command->values[1] * context->unit_scale};
                if (!open) { first = current; open = true; }
                if (!svg_shape_builder_add_edge(builder, current, next))
                    return false;
                current = next;
            } else if (command->verb == SVG_SHAPE_TEXT_CUBIC) {
                geom_point c1 = {gx + command->values[0] * context->unit_scale,
                                 gy - command->values[1] * context->unit_scale};
                geom_point c2 = {gx + command->values[2] * context->unit_scale,
                                 gy - command->values[3] * context->unit_scale};
                geom_point next = {gx + command->values[4] * context->unit_scale,
                                   gy - command->values[5] * context->unit_scale};
                if (!open) { first = current; open = true; }
                if (!svg_shape_builder_add_curve(builder, current, c1, c2,
                                                 next)) return false;
                current = next;
            } else {
                if (open && !svg_shape_builder_add_edge(builder, current, first))
                    return false;
                current = first;
                open = false;
            }
        }
        if (open && !svg_shape_builder_add_edge(builder, current, first))
            return false;
    }
    return true;
}

static bool parse_xml_space(base_bytes source, const svg_xml_token *tokens,
                            size_t count, size_t element,
                            bool parent_preserve, bool *out_preserve,
                            size_t *error_offset)
{
    svg_xml_span span;
    *out_preserve = parent_preserve;
    if (!text_attribute(source, tokens, count, element, "space", "xml",
                        &span)) return true;
    if (svg_css_keyword_equals(source, span, "preserve")) {
        *out_preserve = true;
        return true;
    }
    if (svg_css_keyword_equals(source, span, "default")) {
        *out_preserve = false;
        return true;
    }
    *error_offset = span.offset;
    return false;
}

bool svg_shape_text_render_element(
    svg_shape_builder *builder, base_bytes source, svg_xml_token *tokens,
    size_t token_count, size_t element, size_t end,
    const svg_css_paint *style, geom_affine transform,
    size_t source_offset, size_t source_length,
    svg_shape_text_state *state, bool parent_preserve_space,
    bool *out_preserve_space)
{
    if (builder == NULL || style == NULL || state == NULL ||
        out_preserve_space == NULL || element >= token_count || end >= token_count) {
        svg_shape_fail(builder == NULL ? NULL : builder->diag,
                       SVG_SHAPE_ERROR_INVALID_ARGUMENT, 0U);
        return false;
    }
    size_t error_offset = tokens[element].name.offset;
    bool preserve = parent_preserve_space;
    if (!parse_xml_space(source, tokens, token_count, element,
                         parent_preserve_space, &preserve, &error_offset)) {
        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_UNSUPPORTED,
                       error_offset);
        return false;
    }
    svg_shape_text_family families[SVG_SHAPE_MEDIA_MAX_FAMILIES] = {{0}};
    size_t family_count = 0U;
    svg_shape_text_request request = {0};
    double word_spacing = 0.0;
    bool anchor_middle = false, anchor_end = false;
    if (!parse_text_style(source, style, builder->viewport_width,
                          builder->viewport_height, &request, families,
                          &family_count, &word_spacing, &anchor_middle,
                          &anchor_end, &error_offset)) {
        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_UNSUPPORTED,
                       error_offset);
        return false;
    }
    for (size_t i = element + 1U; i < end; ++i) {
        const svg_xml_token *token = &tokens[i];
        if ((token->kind != SVG_XML_TOKEN_TEXT &&
             token->kind != SVG_XML_TOKEN_CDATA) ||
            token->depth != tokens[element].depth + 1U) continue;
        if (token->value.length > SVG_SHAPE_MEDIA_MAX_TEXT_BYTES ||
            token->value.length > SVG_SHAPE_MEDIA_MAX_DOCUMENT_TEXT_BYTES -
                                  builder->text_bytes) {
            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_LIMIT,
                           token->value.offset);
            return false;
        }
        builder->text_bytes += token->value.length;
        uint8_t *normalized = NULL;
        size_t normalized_length = 0U;
        size_t entity_error = token->value.offset;
        if (!normalize_text(source, token->value, preserve, state,
                            &normalized, &normalized_length, &entity_error)) {
            svg_shape_fail(builder->diag, entity_error == token->value.offset ?
                SVG_SHAPE_ERROR_OOM : SVG_SHAPE_ERROR_UNSUPPORTED,
                entity_error);
            return false;
        }
        if (normalized_length == 0U) {
            svg_shape_free(normalized);
            continue;
        }
        request.text = (base_bytes){normalized, normalized_length};
        svg_shape_text_layout layout = {0};
        bool cached = false;
        if (!svg_shape_text_layout_run(builder->text_cache, &request,
                                       &layout, &cached,
                         builder->diag, token->value.offset)) {
            svg_shape_free(normalized);
            return false;
        }
        if (layout.glyph_count > SVG_SHAPE_MEDIA_MAX_DOCUMENT_GLYPHS -
                                 builder->text_glyphs ||
            layout.command_count > SVG_SHAPE_MEDIA_MAX_DOCUMENT_PATH_COMMANDS -
                                   builder->text_commands) {
            if (!cached) svg_shape_text_layout_release(builder->media, &layout);
            svg_shape_free(normalized);
            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_LIMIT,
                           token->value.offset);
            return false;
        }
        builder->text_glyphs += layout.glyph_count;
        builder->text_commands += layout.command_count;
        size_t outline_commands = 0U;
        for (size_t g = 0U; g < layout.glyph_count; ++g)
            outline_commands += layout.glyphs[g].command_count;
        double x_reference = builder->viewport_width;
        double y_reference = builder->viewport_height;
        double *x_values = NULL, *y_values = NULL;
        double *dx_values = NULL, *dy_values = NULL;
        size_t x_count = 0U, y_count = 0U, dx_count = 0U, dy_count = 0U;
        const char *names[] = {"x", "y", "dx", "dy"};
        double **arrays[] = {&x_values, &y_values, &dx_values, &dy_values};
        size_t *counts[] = {&x_count, &y_count, &dx_count, &dy_count};
        double references[] = {x_reference, y_reference,
                               x_reference, y_reference};
        bool lists_ok = true;
        for (size_t list = 0U; list < 4U; ++list) {
            svg_xml_span position;
            if (text_attribute(source, tokens, token_count, element,
                               names[list], NULL, &position) &&
                !parse_position_list(source, position, references[list],
                    arrays[list], counts[list], &error_offset)) {
                lists_ok = false;
                break;
            }
        }
        if (!lists_ok) {
            svg_shape_free(x_values); svg_shape_free(y_values);
            svg_shape_free(dx_values); svg_shape_free(dy_values);
            if (!cached) svg_shape_text_layout_release(builder->media, &layout);
            svg_shape_free(normalized);
            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_NUMBER,
                           error_offset);
            return false;
        }
        double start_x = state->cursor_x;
        double start_y = state->cursor_y;
        if (x_count != 0U) start_x = x_values[0];
        if (y_count != 0U) start_y = y_values[0];
        if (dx_count != 0U) start_x += dx_values[0];
        if (dy_count != 0U) start_y += dy_values[0];
        const double unit_scale = 96.0 / 72.0;
        double advance_units = layout.advance_width * unit_scale;
        double anchor = anchor_middle ? -advance_units * 0.5 :
                        anchor_end ? -advance_units : 0.0;
        size_t codepoints = 0U, spaces = 0U;
        for (size_t p = 0U; p < normalized_length; ++p) {
            if ((normalized[p] & 0xC0U) != 0x80U) {
                codepoints++;
                if (normalized[p] == ' ') spaces++;
            }
        }
        if (word_spacing != 0.0 && codepoints != layout.glyph_count) {
            svg_shape_free(x_values); svg_shape_free(y_values);
            svg_shape_free(dx_values); svg_shape_free(dy_values);
            if (!cached) svg_shape_text_layout_release(builder->media, &layout);
            svg_shape_free(normalized);
            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_UNSUPPORTED,
                           token->value.offset);
            return false;
        }
        if (outline_commands != 0U) {
            outline_context context = {
                .layout = &layout,
                .x_values = x_values, .x_count = x_count,
                .y_values = y_values, .y_count = y_count,
                .dx_values = dx_values, .dx_count = dx_count,
                .dy_values = dy_values, .dy_count = dy_count,
                .start_x = start_x, .start_y = start_y,
                .anchor_offset = anchor, .unit_scale = unit_scale,
                .word_spacing = word_spacing,
                .text = normalized, .text_length = normalized_length
            };
            size_t first_shape = builder->doc->shape_count;
            if (!svg_shape_builder_add_custom_element(
                    builder, source, tokens, token_count, element, style,
                    transform, text_geometry, &context) ||
                !svg_shape_source_assign(builder->doc, first_shape,
                    builder->doc->shape_count, source_offset, source_length)) {
                svg_shape_free(x_values); svg_shape_free(y_values);
                svg_shape_free(dx_values); svg_shape_free(dy_values);
                if (!cached) svg_shape_text_layout_release(builder->media, &layout);
                svg_shape_free(normalized);
                return false;
            }
        }
        state->cursor_x = start_x + advance_units +
                          (double)spaces * word_spacing;
        state->cursor_y = start_y;
        state->has_position = true;
        svg_shape_free(x_values); svg_shape_free(y_values);
        svg_shape_free(dx_values); svg_shape_free(dy_values);
        if (!cached) svg_shape_text_layout_release(builder->media, &layout);
        svg_shape_free(normalized);
    }
    *out_preserve_space = preserve;
    return true;
}

        y: values[1],
        width: values[2],
        height: values[3],
        draw_x: values[0],
        draw_y: values[1],
        draw_width: values[2],
        draw_height: values[3],
    };
    if let Some([pw, ph]) = pixel_size {
        if pw == 0 || ph == 0 {
            return Err(fail(ErrorKind::Unsupported, tokens[element].name.offset));
        }
        if !aspect.none {
            let sx = g.width / pw as f64;
            let sy = g.height / ph as f64;
            let scale = if aspect.slice { sx.max(sy) } else { sx.min(sy) };
            g.draw_width = pw as f64 * scale;
            g.draw_height = ph as f64 * scale;
            g.draw_x += (g.width - g.draw_width) * aspect.align_x;
            g.draw_y += (g.height - g.draw_height) * aspect.align_y;
        }
    }
    if [
        g.x,
        g.y,
        g.width,
        g.height,
        g.draw_x,
        g.draw_y,
        g.draw_width,
        g.draw_height,
    ]
    .iter()
    .any(|n| !n.is_finite())
    {
        return Err(fail(ErrorKind::Number, tokens[element].name.offset));
    }
    let right = g.x + g.width;
    let bottom = g.y + g.height;
    if [g.x, g.y, right, bottom]
        .iter()
        .any(|v| v.abs() > 1_000_000.)
    {
        return Err(fail(ErrorKind::Number, tokens[element].name.offset));
    }
    Ok(g)
}

/// Call the explicitly supplied decoder and enforce the frozen pixel bounds.
pub fn decode_image(
    provider: &mut dyn MediaProvider,
    encoded: &[u8],
    offset: usize,
    control: &mut dyn WorkControl,
) -> Result<ImagePixels> {
    let pixels = provider
        .decode_image(encoded, control)
        .map_err(|e| media_error(e, offset))?;
    pixels
        .validate(offset)
        .map_err(|_| fail(ErrorKind::Unsupported, offset))?;
    if pixels.width > MAX_IMAGE_DIMENSION || pixels.height > MAX_IMAGE_DIMENSION {
        return Err(fail(ErrorKind::Unsupported, offset));
    }
    let pixel_count = (pixels.width as usize)
        .checked_mul(pixels.height as usize)
        .ok_or_else(|| fail(ErrorKind::Unsupported, offset))?;
    if pixel_count > MAX_TOTAL_IMAGE_PIXELS {
        return Err(fail(ErrorKind::Limit(LimitKind::Images), offset));
    }
    Ok(pixels)
}
/// Rust ownership replaces the old provider release callback.
pub fn release_image(pixels: ImagePixels) {
    drop(pixels);
}

/// Parse one SVG image element and ask the explicit provider to decode inline
/// PNG/JPEG bytes. Zero-area images retain geometry and do not invoke a provider.
pub fn image_element(
    view: vexel_scene::ElementView<'_>,
    viewport: [f64; 2],
    provider: &mut dyn MediaProvider,
    control: &mut dyn WorkControl,
) -> Result<ImagePlan> {
    view.validate(control)?;
    let source = view.source();
    let tokens = view.tokens();
    let element = view.element.0;
    let end = view.end;
    let token = tokens
        .get(element)
        .ok_or_else(|| fail(ErrorKind::InvalidArgument, 0))?;
    let name = token.name;
    let base_geometry = image_geometry(
        source,
        tokens,
        element,
        end,
        viewport,
        None,
        vexel_svg_values::Aspect::default(),
    )?;
    if base_geometry.width == 0. || base_geometry.height == 0. {
        return Ok(ImagePlan {
            geometry: base_geometry,
            pixels: None,
            source: token.source,
        });
    }
    let plain = attribute(source, tokens, element, end, b"href", None);
    let xlink = attribute(source, tokens, element, end, b"href", Some(b"xlink"));
    let href = match (plain, xlink) {
        (Some(_), Some(_)) => return Err(fail(ErrorKind::Unsupported, plain.unwrap().offset)),
        (Some(v), None) => v,
        (None, Some(v)) if xlink_is_bound(source, tokens) => v,
        (None, Some(v)) => return Err(fail(ErrorKind::Unsupported, v.offset)),
        (None, None) => return Err(fail(ErrorKind::Unsupported, name.offset)),
    };
    let payload = parse_data_uri(source, href)?;
    let encoded = decode_base64(source, payload.encoded, control)?;
    let pixels = decode_image(provider, &encoded, href.offset, control)?;
    let aspect =
        if let Some(span) = attribute(source, tokens, element, end, b"preserveAspectRatio", None) {
            vexel_svg_values::parse_preserve_aspect(
                source,
                Span::from_offset_length(span.offset, span.length)
                    .ok_or_else(|| fail(ErrorKind::Unsupported, span.offset))?,
            )
            .map_err(|_| fail(ErrorKind::Unsupported, span.offset))?
        } else {
            vexel_svg_values::Aspect {
                set: true,
                ..Default::default()
            }
        };
    let geometry = image_geometry(
        source,
        tokens,
        element,
        end,
        viewport,
        Some([pixels.width, pixels.height]),
        aspect,
    )?;
    Ok(ImagePlan {
        geometry,
        pixels: Some(pixels),
        source: token.source,
    })
}

/// Decode and append an image through the accepted typed request contract.
/// The host annotation is validated before parsing, provider calls, or mutation,
/// then stored verbatim on the appended shape while `transform` maps geometry.
pub fn decode_image_request(
    request: vexel_scene::ImageDecodeRequest<'_, '_>,
    builder: &mut vexel_scene::SceneBuilder,
    draft: &vexel_scene::DraftToken,
    control: &mut dyn WorkControl,
) -> Result<vexel_scene::ShapeId> {
    request.validate_source_map(builder, control)?;
    let viewport = builder.scene(request.scene)?.viewport;
    let plan = image_element(
        request.element,
        [viewport.view_width, viewport.view_height],
        request.provider,
        control,
    )?;
    append_image_plan_mapped(
        plan,
        request.source_map,
        request.scene,
        request.transform,
        builder,
        draft,
        control,
    )
}

/// Append an owned image and its hit-test geometry inside the caller's real
/// scene draft. Builder reserve/accounting leases own all transferred storage.
pub fn append_image_plan(
    plan: ImagePlan,
    source_assignment: XmlSpan,
    scene: vexel_scene::SceneId,
    transform: vexel_geometry::Affine,
    builder: &mut vexel_scene::SceneBuilder,
    draft: &vexel_scene::DraftToken,
    control: &mut dyn WorkControl,
) -> Result<vexel_scene::ShapeId> {
    let element = Span::from_offset_length(source_assignment.offset, source_assignment.length)
        .ok_or_else(|| fail(ErrorKind::InvalidArgument, source_assignment.offset))?;
    append_image_plan_mapped(
        plan,
        vexel_scene::SourceMap {
            element,
            transform,
            transform_node: None,
        },
        scene,
        transform,
        builder,
        draft,
        control,
    )
}

fn append_image_plan_mapped(
    plan: ImagePlan,
    source_map: vexel_scene::SourceMap,
    scene: vexel_scene::SceneId,
    transform: vexel_geometry::Affine,
    builder: &mut vexel_scene::SceneBuilder,
    draft: &vexel_scene::DraftToken,
    control: &mut dyn WorkControl,
) -> Result<vexel_scene::ShapeId> {
    let source = source_map.element;
    if source.slice(builder.source_owner().as_slice()).is_none() {
        return Err(fail(ErrorKind::InvalidArgument, source.start));
    }
    let geom = plan.geometry;
    let mut image_index = None;
    if let Some(pixels) = plan.pixels {
        let index = builder.append_image(
            scene,
            vexel_scene::Image {
                pixels,
                x: geom.x,
                y: geom.y,
                width: geom.width,
                height: geom.height,
                draw_x: geom.draw_x,
                draw_y: geom.draw_y,
                draw_width: geom.draw_width,
                draw_height: geom.draw_height,
            },
            control,
        )?;
        image_index = Some(index);
    }
    let points = [
        vexel_geometry::Point {
            x: geom.x,
            y: geom.y,
        },
        vexel_geometry::Point {
            x: geom.x + geom.width,
            y: geom.y,
        },
        vexel_geometry::Point {
            x: geom.x + geom.width,
            y: geom.y + geom.height,
        },
        vexel_geometry::Point {
            x: geom.x,
            y: geom.y + geom.height,
        },
    ];
    let mut edges = Vec::new();
    edges
        .try_reserve_exact(4)
        .map_err(|_| fail(ErrorKind::OutOfMemory, plan.source.offset))?;
    for i in 0..4 {
        let a = vexel_geometry::affine_map_point(transform, points[i])
            .ok_or_else(|| fail(ErrorKind::Number, source.start))?;
        let b = vexel_geometry::affine_map_point(transform, points[(i + 1) % 4])
            .ok_or_else(|| fail(ErrorKind::Number, source.start))?;
        edges.push(vexel_geometry::Edge { a, b });
    }
    let mut subpaths = Vec::new();
    subpaths
        .try_reserve_exact(1)
        .map_err(|_| fail(ErrorKind::OutOfMemory, plan.source.offset))?;
    subpaths.push(vexel_svg_path::PathSubpath {
        first_edge: 0,
        edge_count: 4,
        closed: true,
    });
    let path = vexel_svg_path::PathDocument {
        edges,
        subpaths,
        segments: Vec::new(),
        numbers: Vec::new(),
    };
    let mut colors = Vec::new();
    colors
        .try_reserve_exact(4)
        .map_err(|_| fail(ErrorKind::OutOfMemory, plan.source.offset))?;
    colors.resize(4, [0; 4]);
    let mut shape = vexel_scene::Shape::new(source_map);
    shape.image = image_index;
    let id = builder.append_shape(
        scene,
        vexel_scene::ShapeInput {
            shape,
            path,
            edge_colors: colors,
        },
        control,
    )?;
    let published = *builder
        .scene(scene)?
        .shape(id)
        .ok_or_else(|| fail(ErrorKind::InvalidArgument, source.start))?;
    builder.finalize_shape(draft, id, published, control)?;
    Ok(id)
}
fn xlink_is_bound(source: &[u8], tokens: &[XmlToken]) -> bool {
    for (i, token) in tokens.iter().enumerate() {
        if token.kind != TokenKind::StartElement || token.depth != 0 {
            continue;
        }
        for attr in tokens
            .get(i + 1..)
            .unwrap_or_default()
            .iter()
            .take_while(|t| t.kind == TokenKind::Attribute)
        {
            if attr.name.slice(source) == Some(b"xmlns:xlink")
                && attr.value.slice(source) == Some(b"http://www.w3.org/1999/xlink")
            {
                return true;
            }
        }
        return false;
    }
    false
}
fn media_error(error: MediaError, offset: usize) -> Diagnostic {
    let kind = match error {
        MediaError::Unsupported
        | MediaError::Invalid
        | MediaError::InvalidUtf8
        | MediaError::Animated
        | MediaError::Corrupt => ErrorKind::Unsupported,
        MediaError::InvalidArgument => ErrorKind::InvalidArgument,
        MediaError::Limit => ErrorKind::Limit(LimitKind::Images),
        MediaError::OutOfMemory => ErrorKind::OutOfMemory,
    };
    fail(kind, offset)
}
pub fn parse_text_style(
    source: &[u8],
    style: &CssPaint<'_>,
    viewport: [f64; 2],
) -> Result<TextStyleValues> {
    let read_length = |property, reference, default| -> Result<f64> {
        let Some(value) = style.value(property) else {
            return Ok(default);
        };
        vexel_svg_values::parse_length(
            source,
            Span::from_offset_length(value.span.offset, value.span.length)
                .ok_or_else(|| fail(ErrorKind::Number, value.span.offset))?,
            reference,
        )
        .map_err(|_| fail(ErrorKind::Number, value.span.offset))
    };
    let size = read_length(Property::FontSize, viewport[1], 16.)?;
    let size_span = style.value(Property::FontSize).map_or(0, |v| v.span.offset);
    if size <= 0. {
        return Err(fail(ErrorKind::Unsupported, size_span));
    }
    let weight = if let Some(v) = style.value(Property::FontWeight) {
        if v.bytes.eq_ignore_ascii_case(b"normal") {
            400.
        } else if v.bytes.eq_ignore_ascii_case(b"bold") {
            700.
        } else {
            let n = vexel_svg_values::parse_number(
                source,
                Span::from_offset_length(v.span.offset, v.span.length)
                    .ok_or_else(|| fail(ErrorKind::Number, v.span.offset))?,
            )
            .map_err(|_| fail(ErrorKind::Number, v.span.offset))?;
            if !(100. ..=900.).contains(&n) || n % 100. != 0. {
                return Err(fail(ErrorKind::Unsupported, v.span.offset));
            }
            n
        }
    } else {
        400.
    };
    let (families, family_spans) = parse_families_with_spans(source, style)?;
    let spacing = |property| -> Result<f64> {
        let Some(v) = style.value(property) else {
            return Ok(0.);
        };
        if v.bytes.eq_ignore_ascii_case(b"normal") {
            return Ok(0.);
        }
        vexel_svg_values::parse_length(
            source,
            Span::from_offset_length(v.span.offset, v.span.length)
                .ok_or_else(|| fail(ErrorKind::Number, v.span.offset))?,
            viewport[0],
        )
        .map_err(|_| fail(ErrorKind::Number, v.span.offset))
    };
    let text_style = if let Some(v) = style.value(Property::FontStyle) {
        if v.bytes.eq_ignore_ascii_case(b"normal") {
            TextStyle::Normal
        } else if v.bytes.eq_ignore_ascii_case(b"italic") {
            TextStyle::Italic
        } else if v.bytes.eq_ignore_ascii_case(b"oblique") {
            TextStyle::Oblique
        } else {
            return Err(fail(ErrorKind::Unsupported, v.span.offset));
        }
    } else {
        TextStyle::Normal
    };
    let anchor = if let Some(v) = style.value(Property::TextAnchor) {
        if v.bytes.eq_ignore_ascii_case(b"start") {
            vexel_scene::TextAnchor::Start
        } else if v.bytes.eq_ignore_ascii_case(b"middle") {
            vexel_scene::TextAnchor::Middle
        } else if v.bytes.eq_ignore_ascii_case(b"end") {
            vexel_scene::TextAnchor::End
        } else {
            return Err(fail(ErrorKind::Unsupported, v.span.offset));
        }
    } else {
        vexel_scene::TextAnchor::Start
    };
    let letter_spacing = spacing(Property::LetterSpacing)?;
    let word_spacing = spacing(Property::WordSpacing)?;
    Ok(TextStyleValues {
        families,
        family_spans,
        size_points: size * 0.75,
        weight,
        style: text_style,
        anchor,
        letter_spacing_points: letter_spacing * 0.75,
        word_spacing,
    })
}

pub fn parse_xml_space(
    source: &[u8],
    tokens: &[XmlToken],
    element: usize,
    end: usize,
    parent_preserve: bool,
) -> Result<bool> {
    let token = tokens
        .get(element)
        .ok_or_else(|| fail(ErrorKind::InvalidArgument, 0))?;
    for attr in tokens
        .get(element + 1..end.min(tokens.len()))
        .ok_or_else(|| fail(ErrorKind::InvalidArgument, token.name.offset))?
        .iter()
        .take_while(|t| t.kind == vexel_xml::TokenKind::Attribute)
    {
        if attr.local_name.slice(source) != Some(b"space")
            || attr.prefix.slice(source) != Some(b"xml")
        {
            continue;
        }
        return match attr.value.slice(source) {
            Some(v) if v.eq_ignore_ascii_case(b"preserve") => Ok(true),
            Some(v) if v.eq_ignore_ascii_case(b"default") => Ok(false),
            _ => Err(fail(ErrorKind::Unsupported, attr.value.offset)),
        };
    }
    Ok(parent_preserve)
}

/// Legacy helper name retained as a public pure operation for parity.
pub fn text_span_equal(source: &[u8], span: XmlSpan, literal: &[u8]) -> bool {
    span.slice(source) == Some(literal)
}

pub fn text_attribute(
    source: &[u8],
    tokens: &[XmlToken],
    element: usize,
    end: usize,
    local: &[u8],
    prefix: Option<&[u8]>,
) -> Option<XmlSpan> {
    super::image::attribute(source, tokens, element, end, local, prefix)
}

pub fn parse_size(source: &[u8], style: &CssPaint<'_>, viewport_height: f64) -> Result<f64> {
    let Some(v) = style.value(Property::FontSize) else {
        return Ok(16.);
    };
    let value = vexel_svg_values::parse_length(
        source,
        Span::from_offset_length(v.span.offset, v.span.length)
            .ok_or_else(|| fail(ErrorKind::Number, v.span.offset))?,
        viewport_height,
    )
    .map_err(|_| fail(ErrorKind::Number, v.span.offset))?;
    if value <= 0. {
        return Err(fail(ErrorKind::Number, v.span.offset));
    }
    Ok(value)
}

pub fn parse_weight(source: &[u8], style: &CssPaint<'_>) -> Result<f64> {
    let Some(v) = style.value(Property::FontWeight) else {
        return Ok(400.);
    };
    if v.bytes.eq_ignore_ascii_case(b"normal") {
        return Ok(400.);
    }
    if v.bytes.eq_ignore_ascii_case(b"bold") {
        return Ok(700.);
    }
    let n = vexel_svg_values::parse_number(
        source,
        Span::from_offset_length(v.span.offset, v.span.length)
            .ok_or_else(|| fail(ErrorKind::Number, v.span.offset))?,
    )
    .map_err(|_| fail(ErrorKind::Number, v.span.offset))?;
    if !(100. ..=900.).contains(&n) || n % 100. != 0. {
        return Err(fail(ErrorKind::Number, v.span.offset));
    }
    Ok(n)
}

pub fn parse_spacing(
    source: &[u8],
    style: &CssPaint<'_>,
    property: Property,
    reference: f64,
) -> Result<f64> {
    let Some(v) = style.value(property) else {
        return Ok(0.);
    };
    if v.bytes.eq_ignore_ascii_case(b"normal") {
        return Ok(0.);
    }
    vexel_svg_values::parse_length(
        source,
        Span::from_offset_length(v.span.offset, v.span.length)
            .ok_or_else(|| fail(ErrorKind::Number, v.span.offset))?,
        reference,
    )
    .map_err(|_| fail(ErrorKind::Number, v.span.offset))
}
use super::text::{
    MAX_TEXT_BYTES, fail, normalize_text, parse_position_list, parse_text_style, parse_xml_space,
    text_attribute,
};
use vexel_base::WorkControl;
use vexel_scene::{Diagnostic, ErrorKind, LimitKind, Result, TextLayout, TextRequest, TextState};
use vexel_svg_css::CssPaint;
use vexel_xml::XmlToken;

/// Convert provider glyph outlines into the owned flattened path used by the
/// shared scene API. This follows the original 96/72 scale, baseline sign,
/// x/y overrides, accumulated dx/dy, anchor, and word-spacing rules.
pub fn text_geometry(
    layout: &TextLayout,
    text: &[u8],
    x: &[f64],
    y: &[f64],
    dx: &[f64],
    dy: &[f64],
    start: [f64; 2],
    anchor_offset: f64,
    word_spacing: f64,
    transform: vexel_geometry::Affine,
    control: &mut dyn WorkControl,
) -> Result<Vec<vexel_geometry::Edge>> {
    let mut edges = Vec::new();
    let mut codepoint = 0;
    let mut extra_x = 0.;
    let mut extra_y = 0.;
    let mut word_offset = 0.;
    let scale = 96. / 72.;
    for (glyph_index, glyph) in layout.glyphs.iter().enumerate() {
        control.checkpoint().map_err(stopped)?;
        if glyph_index < dx.len() {
            extra_x += dx[glyph_index];
        }
        if glyph_index < dy.len() {
            extra_y += dy[glyph_index];
        }
        let x_override = glyph_index < x.len();
        let y_override = glyph_index < y.len();
        if x_override {
            extra_x = 0.;
        }
        if y_override {
            extra_y = 0.;
        }
        let gx = (if x_override {
            x[glyph_index]
        } else {
            start[0] + glyph.x * scale
        }) + extra_x
            + anchor_offset
            + word_offset;
        let gy = (if y_override {
            y[glyph_index]
        } else {
            start[1] - glyph.y * scale
        }) + extra_y;
        while codepoint < text.len() && text[codepoint] & 0xc0 == 0x80 {
            codepoint += 1;
        }
        if codepoint < text.len() && text[codepoint] == b' ' {
            word_offset += word_spacing;
        }
        while codepoint < text.len() && text[codepoint] & 0xc0 != 0x80 {
            codepoint += 1;
        }
        let range_end = glyph
            .commands
            .first
            .checked_add(glyph.commands.count)
            .filter(|&end| end <= layout.commands.len())
            .ok_or_else(|| fail(ErrorKind::Unsupported, 0))?;
        let mut current = vexel_geometry::Point { x: 0., y: 0. };
        let mut first = current;
        let mut open = false;
        for command in &layout.commands[glyph.commands.first..range_end] {
            let point = |i: usize| vexel_geometry::Point {
                x: gx + command.values[i] * scale,
                y: gy - command.values[i + 1] * scale,
            };
            match command.verb {
                vexel_scene::TextVerb::Move => {
                    if open {
                        append_text_edge(current, first, transform, &mut edges, control)?;
                    }
                    current = point(0);
                    first = current;
                    open = true;
                }
                vexel_scene::TextVerb::Line => {
                    let next = point(0);
                    if !open {
                        first = current;
                        open = true;
                    }
                    append_text_edge(current, next, transform, &mut edges, control)?;
                    current = next;
                }
                vexel_scene::TextVerb::Cubic => {
                    let c1 = point(0);
                    let c2 = point(2);
                    let next = point(4);
                    if !open {
                        first = current;
                        open = true;
                    }
                    vexel_svg_path::flatten_cubic_controlled(
                        [current, c1, c2, next],
                        transform,
                        vexel_svg_path::ParseOptions::default(),
                        0,
                        &mut edges,
                        control,
                    )
                    .map_err(path_control_error)?;
                    current = next;
                }
                vexel_scene::TextVerb::Close => {
                    if open {
                        append_text_edge(current, first, transform, &mut edges, control)?;
                    }
                    current = first;
                    open = false;
                }
            }
        }
        if open {
            append_text_edge(current, first, transform, &mut edges, control)?;
        }
    }
    Ok(edges)
}

/// Decode direct text/CDATA children of a text or tspan element. Each authored
/// run creates one owned scene shape, with source identity fixed at append time.
/// The caller retains the outer draft token and rolls it back if this returns an
/// error; shape finalization checks that token against the actual SceneBuilder.
pub fn render_text_request(
    request: vexel_scene::TextDecodeRequest<'_, '_>,
    builder: &mut vexel_scene::SceneBuilder,
    draft: &vexel_scene::DraftToken,
    control: &mut dyn WorkControl,
) -> Result<bool> {
    request.validate_source_map(builder, control)?;
    let source_map = request.source_map;
    render_text_element(
        request.element,
        request.scene,
        source_map,
        request.style,
        request.transform,
        request.state,
        request.preserve_space,
        request.provider,
        request.cache,
        builder,
        draft,
        control,
    )
}

fn render_text_element(
    view: vexel_scene::ElementView<'_>,
    scene: vexel_scene::SceneId,
    source_map: vexel_scene::SourceMap,
    style: &CssPaint<'_>,
    transform: vexel_geometry::Affine,
    state: &mut TextState,
    parent_preserve_space: bool,
    provider: &mut dyn vexel_scene::MediaProvider,
    cache: &mut vexel_scene::TextCache,
    builder: &mut vexel_scene::SceneBuilder,
    draft: &vexel_scene::DraftToken,
    control: &mut dyn WorkControl,
) -> Result<bool> {
    view.validate(control)?;
    let source = view.source();
    let tokens = view.tokens();
    let element = view.element.0;
    let end = view.end;
    if source_map.element.slice(source).is_none() {
        return Err(fail(ErrorKind::InvalidArgument, source_map.element.start));
    }
    let preserve = parse_xml_space(source, tokens, element, end, parent_preserve_space)?;
    let viewport = builder.scene(scene)?.viewport;
    let viewport_size = [viewport.view_width, viewport.view_height];
    let values = parse_text_style(source, style, viewport_size)?;
    let mut family_refs: Vec<&[u8]> = Vec::new();
    family_refs
        .try_reserve_exact(values.families.len())
        .map_err(|_| fail(ErrorKind::OutOfMemory, tokens[element].name.offset))?;
    family_refs.extend(values.families.iter().map(Vec::as_slice));
    for token in tokens
        .get(element + 1..end)
        .ok_or_else(|| fail(ErrorKind::InvalidArgument, 0))?
    {
        control
            .charge(vexel_base::WorkKind::TokenVisit, 1)
            .map_err(stopped)?;
        if token.depth > tokens[element].depth
            && matches!(
                token.kind,
                vexel_xml::TokenKind::StartElement | vexel_xml::TokenKind::EmptyElement
            )
            && token.local_name.slice(source) == Some(b"textPath")
        {
            return Err(fail(ErrorKind::Unsupported, token.name.offset));
        }
    }
    for token in tokens
        .get(element + 1..end)
        .ok_or_else(|| fail(ErrorKind::InvalidArgument, 0))?
    {
        control
            .charge(vexel_base::WorkKind::TokenVisit, 1)
            .map_err(stopped)?;
        if !matches!(
            token.kind,
            vexel_xml::TokenKind::Text | vexel_xml::TokenKind::Cdata
        ) || token.depth != tokens[element].depth + 1
        {
            continue;
        }
        if token.value.length > MAX_TEXT_BYTES
            || state.text_bytes > 64 * 1024 * 1024
            || token.value.length > (64 * 1024 * 1024usize).saturating_sub(state.text_bytes)
        {
            return Err(fail(
                ErrorKind::Limit(LimitKind::TextBytes),
                token.value.offset,
            ));
        }
        state.text_bytes = state
            .text_bytes
            .checked_add(token.value.length)
            .ok_or_else(|| fail(ErrorKind::Limit(LimitKind::Arithmetic), token.value.offset))?;
        let normalized = normalize_text(source, token.value, preserve, state)?;
        if normalized.is_empty() {
            continue;
        }
        let request = TextRequest {
            text: &normalized,
            font_families: &family_refs,
            size_points: values.size_points,
            weight: values.weight,
            style: values.style,
            letter_spacing_points: values.letter_spacing_points,
        };
        let output = super::text_cache::layout_shared(
            cache,
            request,
            &values.family_spans,
            provider,
            control,
            token.value.offset,
        )?;
        let layout = output.layout();
        if state.glyph_count > 1_048_576usize
            || layout.glyphs.len() > 1_048_576usize - state.glyph_count
            || layout.commands.len() > 4 * 1024 * 1024usize
        {
            return Err(fail(
                ErrorKind::Limit(LimitKind::Glyphs),
                token.value.offset,
            ));
        }
        state.glyph_count = state
            .glyph_count
            .checked_add(layout.glyphs.len())
            .ok_or_else(|| fail(ErrorKind::Limit(LimitKind::Arithmetic), token.value.offset))?;
        let x = parse_positions_if_present(source, tokens, element, end, b"x", viewport_size[0])?;
        let y = parse_positions_if_present(source, tokens, element, end, b"y", viewport_size[1])?;
        let dx = parse_positions_if_present(source, tokens, element, end, b"dx", viewport_size[0])?;
        let dy = parse_positions_if_present(source, tokens, element, end, b"dy", viewport_size[1])?;
        let start_x =
            x.first().copied().unwrap_or(state.cursor_x) + dx.first().copied().unwrap_or(0.);
        let start_y =
            y.first().copied().unwrap_or(state.cursor_y) + dy.first().copied().unwrap_or(0.);
        let codepoints = normalized.iter().filter(|b| **b & 0xc0 != 0x80).count();
        let spaces = normalized.iter().filter(|b| **b == b' ').count();
        if values.word_spacing != 0. && codepoints != layout.glyphs.len() {
            return Err(fail(ErrorKind::Unsupported, token.value.offset));
        }
        let anchor_offset = match values.anchor {
            vexel_scene::TextAnchor::Start => 0.,
            vexel_scene::TextAnchor::Middle => -layout.advance_width * (96. / 72.) * 0.5,
            vexel_scene::TextAnchor::End => -layout.advance_width * (96. / 72.),
        };
        if layout.glyphs.iter().any(|g| g.commands.count != 0) {
            let edges = text_geometry(
                layout,
                &normalized,
                &x,
                &y,
                &dx,
                &dy,
                [start_x, start_y],
                anchor_offset,
                values.word_spacing,
                transform,
                control,
            )?;
            if !edges.is_empty() {
                let mut colors = Vec::new();
                colors
                    .try_reserve_exact(edges.len())
                    .map_err(|_| fail(ErrorKind::OutOfMemory, token.value.offset))?;
                colors.resize(edges.len(), [0; 4]);
                let mut subpaths = Vec::new();
                subpaths
                    .try_reserve_exact(1)
                    .map_err(|_| fail(ErrorKind::OutOfMemory, token.value.offset))?;
                subpaths.push(vexel_svg_path::PathSubpath {
                    first_edge: 0,
                    edge_count: edges.len(),
                    closed: true,
                });
                let path = vexel_svg_path::PathDocument {
                    subpaths,
                    edges,
                    segments: Vec::new(),
                    numbers: Vec::new(),
                };
                let mut shape = vexel_scene::Shape::new(source_map);
                shape.filled = true;
                let id = builder.append_shape(
                    scene,
                    vexel_scene::ShapeInput {
                        shape,
                        path,
                        edge_colors: colors,
                    },
                    control,
                )?;
                let published = *builder
                    .scene(scene)?
                    .shape(id)
                    .ok_or_else(|| fail(ErrorKind::InvalidArgument, source_map.element.start))?;
                builder.finalize_shape(draft, id, published, control)?;
            }
        }
        state.cursor_x =
            start_x + layout.advance_width * (96. / 72.) + spaces as f64 * values.word_spacing;
        state.cursor_y = start_y;
        state.has_position = true;
    }
    Ok(preserve)
}

fn parse_positions_if_present(
    source: &[u8],
    tokens: &[XmlToken],
    element: usize,
    end: usize,
    name: &[u8],
    reference: f64,
) -> Result<Vec<f64>> {
    match text_attribute(source, tokens, element, end, name, None) {
        Some(span) => parse_position_list(source, span, reference),
        None => Ok(Vec::new()),
    }
}

fn append_text_edge(
    from: vexel_geometry::Point,
    to: vexel_geometry::Point,
    transform: vexel_geometry::Affine,
    edges: &mut Vec<vexel_geometry::Edge>,
    control: &mut dyn WorkControl,
) -> Result<()> {
    vexel_svg_path::append_edge(
        from,
        to,
        transform,
        vexel_svg_path::MAX_PATH_EDGES,
        0,
        edges,
    )
    .map_err(path_error)?;
    control
        .charge(vexel_base::WorkKind::Edge, 1)
        .map_err(stopped)
}
fn stopped(stop: vexel_base::Stop) -> Diagnostic {
    Diagnostic {
        kind: match stop {
            vexel_base::Stop::Canceled => ErrorKind::Canceled,
            vexel_base::Stop::Limit => ErrorKind::Limit(LimitKind::Work),
            vexel_base::Stop::Overflow => ErrorKind::Limit(LimitKind::Arithmetic),
        },
        offset: 0,
    }
}
fn path_error(error: vexel_svg_path::Diagnostic) -> Diagnostic {
    Diagnostic {
        kind: match error.kind {
            vexel_svg_path::DiagnosticKind::Limit => ErrorKind::Limit(LimitKind::PathCommands),
            vexel_svg_path::DiagnosticKind::OutOfMemory => ErrorKind::OutOfMemory,
            vexel_svg_path::DiagnosticKind::Number
            | vexel_svg_path::DiagnosticKind::InvalidTransform => ErrorKind::Number,
            _ => ErrorKind::Unsupported,
        },
        offset: error.offset,
    }
}
fn path_control_error(
    error: vexel_base::ControlledError<vexel_svg_path::Diagnostic>,
) -> Diagnostic {
    match error {
        vexel_base::ControlledError::Original(error) => path_error(error),
        vexel_base::ControlledError::Canceled => stopped(vexel_base::Stop::Canceled),
        vexel_base::ControlledError::Limit => stopped(vexel_base::Stop::Limit),
        vexel_base::ControlledError::Overflow => stopped(vexel_base::Stop::Overflow),
        vexel_base::ControlledError::OutOfMemory => Diagnostic {
            kind: ErrorKind::OutOfMemory,
            offset: 0,
        },
    }
}
use super::image::ImageGeometry;
use vexel_geometry::{Affine, Point, affine_map_point};
use vexel_scene::ImagePixels;

/// Sample one placed image at a document-space point using the frozen half-open
/// bounds and bilinear interpolation of premultiplied RGBA8 pixels. Returned
/// color is straight RGBA8 for the compositor, with nearest-integer rounding.
pub fn sample_image(
    image: &ImagePixels,
    geometry: ImageGeometry,
    inverse_transform: Affine,
    x: f64,
    y: f64,
) -> Option<[u8; 4]> {
    if image.validate(0).is_err()
        || image.width == 0
        || image.height == 0
        || geometry.draw_width <= 0.
        || geometry.draw_height <= 0.
    {
        return None;
    }
    let local = affine_map_point(inverse_transform, Point { x, y })?;
    let right = geometry.x + geometry.width;
    let bottom = geometry.y + geometry.height;
    let draw_right = geometry.draw_x + geometry.draw_width;
    let draw_bottom = geometry.draw_y + geometry.draw_height;
    if ![local.x, local.y, right, bottom, draw_right, draw_bottom]
        .iter()
        .all(|v| v.is_finite())
        || local.x < geometry.x
        || local.y < geometry.y
        || local.x >= right
        || local.y >= bottom
        || local.x < geometry.draw_x
        || local.y < geometry.draw_y
        || local.x >= draw_right
        || local.y >= draw_bottom
    {
        return None;
    }
    let u = (local.x - geometry.draw_x) / geometry.draw_width;
    let v = (local.y - geometry.draw_y) / geometry.draw_height;
    let mut sx = u * f64::from(image.width) - 0.5;
    let mut sy = v * f64::from(image.height) - 0.5;
    sx = sx.clamp(0., f64::from(image.width - 1));
    sy = sy.clamp(0., f64::from(image.height - 1));
    let x0 = sx.floor() as u32;
    let y0 = sy.floor() as u32;
    let x1 = if x0 + 1 < image.width { x0 + 1 } else { x0 };
    let y1 = if y0 + 1 < image.height { y0 + 1 } else { y0 };
    let fx = sx - f64::from(x0);
    let fy = sy - f64::from(y0);
    let p00 = pixel(image, x0, y0)?;
    let p10 = pixel(image, x1, y0)?;
    let p01 = pixel(image, x0, y1)?;
    let p11 = pixel(image, x1, y1)?;
    let mut channels = [0.; 4];
    for (channel, out) in channels.iter_mut().enumerate() {
        let top = f64::from(p00[channel]) * (1. - fx) + f64::from(p10[channel]) * fx;
        let lower = f64::from(p01[channel]) * (1. - fx) + f64::from(p11[channel]) * fx;
        *out = top * (1. - fy) + lower * fy;
    }
    let alpha = (channels[3] + 0.5).floor().clamp(0., 255.) as u8;
    if alpha == 0 {
        return Some([0; 4]);
    }
    let mut result = [0; 4];
    for channel in 0..3 {
        result[channel] = (channels[channel] * 255. / channels[3] + 0.5)
            .floor()
            .clamp(0., 255.) as u8;
    }
    result[3] = alpha;
    Some(result)
}

fn pixel(image: &ImagePixels, x: u32, y: u32) -> Option<[u8; 4]> {
    let offset = (y as usize)
        .checked_mul(image.row_stride)?
        .checked_add((x as usize).checked_mul(4)?)?;
    let end = offset.checked_add(4)?;
    let pixel = image.rgba.get(offset..end)?;
    Some([pixel[0], pixel[1], pixel[2], pixel[3]])
}

#include "shape.h"
#include "shape_render.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct fake_media_state {
    size_t layout_calls;
    size_t text_releases;
    size_t image_calls;
    size_t image_releases;
    char last_text[128];
    size_t last_text_length;
    char last_family[64];
    char first_family[64];
    double last_size;
    double first_size;
    double last_weight;
    double first_weight;
    svg_shape_text_style last_style;
    svg_shape_text_style first_style;
    double last_letter_spacing;
    double first_letter_spacing;
} fake_media_state;

static size_t count_codepoints(base_bytes text)
{
    size_t count = 0U;
    for (size_t i = 0U; i < text.len; ++i)
        if ((text.ptr[i] & 0xC0U) != 0x80U) count++;
    return count;
}

static svg_shape_media_status fake_layout_text(
    void *opaque, const svg_shape_text_request *request,
    svg_shape_text_layout *out)
{
    fake_media_state *state = opaque;
    if (request == NULL || out == NULL || request->text.len > 127U)
        return SVG_SHAPE_MEDIA_INVALID;
    state->layout_calls++;
    memcpy(state->last_text, request->text.ptr, request->text.len);
    state->last_text[request->text.len] = '\0';
    state->last_text_length = request->text.len;
    state->last_family[0] = '\0';
    if (request->font_family_count != 0U) {
        size_t length = request->font_families[0].length;
        if (length >= sizeof(state->last_family)) return SVG_SHAPE_MEDIA_LIMIT;
        memcpy(state->last_family, request->font_families[0].bytes, length);
        state->last_family[length] = '\0';
    }
    state->last_size = request->size_points;
    state->last_weight = request->weight;
    state->last_style = request->style;
    state->last_letter_spacing = request->letter_spacing_points;
    if (state->layout_calls == 1U) {
        memcpy(state->first_family, state->last_family,
               sizeof(state->first_family));
        state->first_size = state->last_size;
        state->first_weight = state->last_weight;
        state->first_style = state->last_style;
        state->first_letter_spacing = state->last_letter_spacing;
    }
    size_t glyph_count = count_codepoints(request->text);
    size_t drawable = 0U;
    for (size_t i = 0U; i < request->text.len; ++i)
        if (request->text.ptr[i] != ' ' &&
            (request->text.ptr[i] & 0xC0U) != 0x80U) drawable++;
    if (drawable > SIZE_MAX / 5U || glyph_count > SIZE_MAX / sizeof(svg_shape_text_glyph))
        return SVG_SHAPE_MEDIA_LIMIT;
    size_t command_count = drawable * 5U;
    svg_shape_text_glyph *glyphs = glyph_count == 0U ? NULL :
        calloc(glyph_count, sizeof(*glyphs));
    svg_shape_text_command *commands = command_count == 0U ? NULL :
        calloc(command_count, sizeof(*commands));
    if ((glyph_count != 0U && glyphs == NULL) ||
        (command_count != 0U && commands == NULL)) {
        free(glyphs);
        free(commands);
        return SVG_SHAPE_MEDIA_OOM;
    }
    size_t glyph = 0U, command = 0U;
    for (size_t i = 0U; i < request->text.len; ++i) {
        uint8_t byte = request->text.ptr[i];
        if ((byte & 0xC0U) == 0x80U) continue;
        size_t first = command;
        size_t count = 0U;
        if (byte != ' ') {
            commands[command++] = (svg_shape_text_command){
                SVG_SHAPE_TEXT_MOVE, {0.0, 0.0}};
            commands[command++] = (svg_shape_text_command){
                SVG_SHAPE_TEXT_LINE, {6.0, 0.0}};
            commands[command++] = (svg_shape_text_command){
                SVG_SHAPE_TEXT_LINE, {6.0, 8.0}};
            commands[command++] = (svg_shape_text_command){
                SVG_SHAPE_TEXT_LINE, {0.0, 8.0}};
            commands[command++] = (svg_shape_text_command){
                SVG_SHAPE_TEXT_CLOSE, {0.0}};
            count = 5U;
        }
        glyphs[glyph] = (svg_shape_text_glyph){
            (double)glyph * 8.0, 0.0, 8.0, first, count};
        glyph++;
    }
    *out = (svg_shape_text_layout){glyphs, glyph_count, commands,
        command_count, (double)glyph_count * 8.0, 9.0, 3.0, 0.0};
    return SVG_SHAPE_MEDIA_OK;
}

static void fake_text_release(void *opaque, svg_shape_text_layout *layout)
{
    fake_media_state *state = opaque;
    if (state != NULL) state->text_releases++;
    free(layout->glyphs);
    free(layout->commands);
    *layout = (svg_shape_text_layout){0};
}

static const uint8_t fake_pixels[16] = {
    255U, 0U, 0U, 255U, 0U, 255U, 0U, 255U,
    0U, 0U, 255U, 255U, 255U, 255U, 255U, 255U
};

static svg_shape_media_status fake_decode_image(
    void *opaque, base_bytes encoded, svg_shape_decoded_image *out)
{
    fake_media_state *state = opaque;
    if (encoded.len != 3U || encoded.ptr[0] != 1U ||
        encoded.ptr[1] != 2U || encoded.ptr[2] != 3U)
        return SVG_SHAPE_MEDIA_INVALID;
    state->image_calls++;
    *out = (svg_shape_decoded_image){fake_pixels, sizeof(fake_pixels),
                                     8U, 2U, 2U, state};
    return SVG_SHAPE_MEDIA_OK;
}

static void fake_image_release(void *opaque, svg_shape_decoded_image *image)
{
    fake_media_state *state = opaque;
    if (state != NULL) state->image_releases++;
    *image = (svg_shape_decoded_image){0};
}

static svg_shape_media_providers fake_providers(fake_media_state *state)
{
    return (svg_shape_media_providers){
        .context = state,
        .layout_text = fake_layout_text,
        .release_text = fake_text_release,
        .decode_image = fake_decode_image,
        .release_image = fake_image_release
    };
}

static bool check(bool condition, const char *message)
{
    if (!condition) fprintf(stderr, "text/image check failed: %s\n", message);
    return condition;
}

static bool text_checks(void)
{
    static const char source[] =
        "<svg width=\"80\" height=\"40\"><style>"
        ".label{font-family:'Mock Sans',sans-serif;font-size:12px;"
        "font-weight:700;font-style:italic;text-anchor:middle;"
        "letter-spacing:2px;word-spacing:1px;fill:red}"
        "</style><g class=\"label\"><text x=\"30\" y=\"20\">A B"
        "<tspan dx=\"2\" fill=\"blue\">C</tspan></text></g>"
        "<text x=\"50\" y=\"20\">A</text>"
        "<text x=\"60\" y=\"20\">A</text></svg>";
    fake_media_state state = {0};
    svg_shape_media_providers providers = fake_providers(&state);
    svg_shape_document document = {0};
    svg_shape_diagnostic diagnostic = {0};
    base_bytes bytes = {(const uint8_t *)source, sizeof(source) - 1U};
    bool decoded = svg_shape_decode_with_media(bytes, &providers, &document,
                                                &diagnostic) == SVG_SHAPE_ERROR_NONE;
    if (!check(decoded, "CSS text and nested tspan decode")) return false;
    bool okay = check(document.shape_count == 4U,
                      "one outline shape per text run") &&
        check(state.layout_calls == 3U,
              "identical shaped run reuses the decode-local cache") &&
        check(strcmp(state.first_family, "Mock Sans") == 0,
              "font-family list strips CSS quotes") &&
        check(fabs(state.first_size - 9.0) < 1e-12 &&
              state.first_weight == 700.0 &&
              state.first_style == SVG_SHAPE_TEXT_ITALIC &&
              fabs(state.first_letter_spacing - 1.5) < 1e-12,
              "inherited size, weight, style and spacing reach provider") &&
        check(document.shape_sources[0].offset ==
              (size_t)(strstr(source, "<text") - source),
              "text shape has source element mapping") &&
        check(document.shape_count == 4U && document.edge_count != 0U,
              "CoreText outlines enter the path edge pipeline");
    svg_shape_document_destroy(&document);
    okay = okay && check(state.text_releases == 3U,
                         "cache releases each owned shaped run once");

    static const char whitespace[] =
        "<svg width=\"20\" height=\"10\"><text>A   B</text>"
        "<text xml:space=\"preserve\"> A  B </text></svg>";
    memset(&state, 0, sizeof(state));
    providers = fake_providers(&state);
    decoded = svg_shape_decode_with_media(
        (base_bytes){(const uint8_t *)whitespace, sizeof(whitespace) - 1U},
        &providers, &document, &diagnostic) == SVG_SHAPE_ERROR_NONE;
    okay = okay && check(decoded && state.layout_calls == 2U,
                         "xml:space modes produce two text runs");
    if (decoded) svg_shape_document_destroy(&document);
    okay = okay && check(strcmp(state.last_text, " A  B ") == 0,
                         "xml:space preserve keeps authored whitespace");

    static const char no_provider[] =
        "<svg width=\"8\" height=\"8\"><text>x</text></svg>";
    svg_shape_error no_media = svg_shape_decode(
        (base_bytes){(const uint8_t *)no_provider, sizeof(no_provider) - 1U},
        &document, &diagnostic);
    okay = okay && check(no_media == SVG_SHAPE_ERROR_UNSUPPORTED &&
                         diagnostic.category == SVG_SHAPE_ERROR_UNSUPPORTED,
                         "text without an injected provider fails closed");
    static const char text_path[] =
        "<svg width=\"8\" height=\"8\"><text><textPath href=\"#p\">x"
        "</textPath></text></svg>";
    providers = fake_providers(&state);
    no_media = svg_shape_decode_with_media(
        (base_bytes){(const uint8_t *)text_path, sizeof(text_path) - 1U},
        &providers, &document, &diagnostic);
    okay = okay && check(no_media == SVG_SHAPE_ERROR_UNSUPPORTED,
                         "textPath has a stable unsupported result");
    return okay;
}

static bool text_use_symbol_checks(void)
{
    static const char source[] =
        "<svg width=\"32\" height=\"16\"><defs>"
        "<text id=\"plain\" x=\"2\" y=\"8\">U</text>"
        "<symbol id=\"mark\" viewBox=\"0 0 8 8\"><text x=\"1\" y=\"6\">S"
        "</text></symbol></defs><use href=\"#plain\" x=\"3\"/>"
        "<use href=\"#mark\" x=\"14\" y=\"2\" width=\"8\" height=\"8\"/>"
        "</svg>";
    fake_media_state state = {0};
    svg_shape_media_providers providers = fake_providers(&state);
    svg_shape_document document = {0};
    svg_shape_diagnostic diagnostic = {0};
    bool decoded = svg_shape_decode_with_media(
        (base_bytes){(const uint8_t *)source, sizeof(source) - 1U},
        &providers, &document, &diagnostic) == SVG_SHAPE_ERROR_NONE;
    if (!check(decoded, "text under use and symbol decodes")) return false;
    const char *first_use = strstr(source, "<use");
    const char *second_use = first_use == NULL ? NULL : strstr(first_use + 4, "<use");
    bool okay = check(document.shape_count == 2U && state.layout_calls == 2U,
                      "referenced text is shaped once per source run") &&
        check(first_use != NULL && second_use != NULL &&
              document.shape_sources[0].offset == (size_t)(first_use - source) &&
              document.shape_sources[1].offset == (size_t)(second_use - source),
              "referenced text selection maps to each host use element") &&
        check(document.edges[0].a.x >= 5.0 && document.edges[0].a.x < 9.0,
              "text use-site translation reaches glyph outline geometry");
    svg_shape_document_destroy(&document);
    okay = okay && check(state.text_releases == 2U,
                         "referenced text layouts release after decode");
    return okay;
}

static bool image_checks(void)
{
    static const char source[] =
        "<svg width=\"4\" height=\"2\"><image x=\"0\" y=\"0\""
        " width=\"4\" height=\"2\" preserveAspectRatio=\"xMidYMid meet\""
        " href=\"data:image/png;base64,AQID\"/></svg>";
    fake_media_state state = {0};
    svg_shape_media_providers providers = fake_providers(&state);
    svg_shape_document document = {0};
    svg_shape_diagnostic diagnostic = {0};
    bool decoded = svg_shape_decode_with_media(
        (base_bytes){(const uint8_t *)source, sizeof(source) - 1U},
        &providers, &document, &diagnostic) == SVG_SHAPE_ERROR_NONE;
    if (!check(decoded, "embedded PNG data URI is decoded")) return false;
    bool okay = check(state.image_calls == 1U && document.shape_count == 1U,
                      "image data is handed to injected provider") &&
        check(fabs(document.images[0].draw_x - 1.0) < 1e-12 &&
              fabs(document.images[0].draw_width - 2.0) < 1e-12,
              "meet preserves aspect ratio with centered letterbox") &&
        check(document.shape_sources[0].length != 0U,
              "image shape has source mapping");
    raster_tile tile = {0};
    bool rendered = raster_shape_render(&document, &tile, &diagnostic);
    okay = okay && check(rendered && tile.width == 4U && tile.height == 2U,
                         "embedded image reaches scalar rasterizer");
    if (rendered) {
        size_t first_alpha = tile.rgba[3U];
        size_t second_alpha = tile.rgba[(size_t)1U * 4U + 3U];
        size_t third_alpha = tile.rgba[(size_t)2U * 4U + 3U];
        okay = okay && check(first_alpha == 0U && second_alpha != 0U &&
                             third_alpha != 0U,
                             "meet letterbox and bilinear image coverage");
        raster_tile_destroy(&tile);
    }
    svg_shape_document_destroy(&document);
    okay = okay && check(state.image_releases == 1U,
                         "decoded image ownership releases with document");

    static const char scaled[] =
        "<svg width=\"4\" height=\"4\"><image width=\"4\" height=\"4\""
        " preserveAspectRatio=\"none\""
        " href=\"data:image/png;base64,AQID\"/></svg>";
    memset(&state, 0, sizeof(state));
    providers = fake_providers(&state);
    decoded = svg_shape_decode_with_media(
        (base_bytes){(const uint8_t *)scaled, sizeof(scaled) - 1U},
        &providers, &document, &diagnostic) == SVG_SHAPE_ERROR_NONE;
    raster_tile scaled_tile = {0};
    rendered = decoded && raster_shape_render(&document, &scaled_tile,
                                               &diagnostic);
    const uint8_t *interpolated = rendered ?
        scaled_tile.rgba + (size_t)(1U * scaled_tile.width + 1U) * 4U : NULL;
    okay = okay && check(rendered && interpolated != NULL &&
                         interpolated[0] == 159U && interpolated[1] == 64U &&
                         interpolated[2] == 64U && interpolated[3] == 255U,
                         "scaled 2x2 image uses premultiplied bilinear sampling");
    if (rendered) raster_tile_destroy(&scaled_tile);
    if (decoded) svg_shape_document_destroy(&document);

    static const char transformed[] =
        "<svg width=\"4\" height=\"2\"><image transform=\"translate(1 0)\""
        " width=\"1\" height=\"1\" preserveAspectRatio=\"none\""
        " href=\"data:image/jpeg;base64,AQID\"/></svg>";
    memset(&state, 0, sizeof(state));
    providers = fake_providers(&state);
    decoded = svg_shape_decode_with_media(
        (base_bytes){(const uint8_t *)transformed, sizeof(transformed) - 1U},
        &providers, &document, &diagnostic) == SVG_SHAPE_ERROR_NONE;
    okay = okay && check(decoded && state.image_calls == 1U &&
                         fabs(document.shape_sources[0].transform.e - 1.0) < 1e-12,
                         "JPEG data URI and element transform are retained");
    if (decoded) svg_shape_document_destroy(&document);

    static const char external[] =
        "<svg width=\"8\" height=\"8\"><image width=\"2\" height=\"2\""
        " href=\"https://example.invalid/p.png\"/></svg>";
    svg_shape_error error = svg_shape_decode_with_media(
        (base_bytes){(const uint8_t *)external, sizeof(external) - 1U},
        &providers, &document, &diagnostic);
    okay = okay && check(error == SVG_SHAPE_ERROR_UNSUPPORTED &&
                         state.image_calls == 1U,
                         "external image references are rejected without fetch");
    static const char malformed[] =
        "<svg width=\"8\" height=\"8\"><image width=\"2\" height=\"2\""
        " href=\"data:image/png;base64,AQ!D\"/></svg>";
    error = svg_shape_decode_with_media(
        (base_bytes){(const uint8_t *)malformed, sizeof(malformed) - 1U},
        &providers, &document, &diagnostic);
    okay = okay && check(error == SVG_SHAPE_ERROR_UNSUPPORTED,
                         "malformed base64 has a stable diagnostic");
    return okay;
}

static bool selection_and_path_checks(void)
{
    static const char source[] =
        "<svg width=\"16\" height=\"16\"><defs><rect id=\"r\" width=\"4\""
        " height=\"4\"/></defs><use href=\"#r\" x=\"2\" y=\"3\"/>"
        "<path d=\"M1 1 L7 1 L7 7 Z\" fill=\"blue\"/></svg>";
    svg_shape_document document = {0};
    svg_shape_diagnostic diagnostic = {0};
    if (svg_shape_decode((base_bytes){(const uint8_t *)source,
                                      sizeof(source) - 1U},
                         &document, &diagnostic) != SVG_SHAPE_ERROR_NONE)
        return check(false, "source map fixture decodes");
    const char *use = strstr(source, "<use");
    const char *path = strstr(source, "<path");
    bool okay = check(document.shape_count == 2U && use != NULL && path != NULL,
                      "use and authored path create shapes") &&
        check(document.shape_sources[0].offset == (size_t)(use - source),
              "use instance maps to host use element") &&
        check(document.path_segment_count == 4U &&
              document.path_number_count == 6U,
              "path command topology retains every numeric source span") &&
        check(document.path_segments[0].command == 'M' &&
              document.path_segments[0].command_offset ==
                  (size_t)(strstr(source, "M1 1") - source),
              "path command span points into original d source") &&
        check(document.path_numbers[0].offset ==
                  (size_t)(strstr(source, "M1 1") - source) + 1U &&
              document.path_numbers[0].length == 1U &&
              document.path_numbers[0].value == 1.0 &&
              document.path_numbers[5].value == 7.0,
              "each path number retains its literal source span and value");
    svg_shape_selection selection = {0};
    okay = okay && check(svg_shape_hit_test(&document, 3.0, 3.0, 0.0,
                                             &selection) &&
                         selection.source_offset == (size_t)(path - source),
                         "topmost hit test returns source-backed shape") &&
        check(svg_shape_bounds_query(&document, 0U, &selection) &&
              fabs(selection.user_bounds.x - 2.0) < 1e-12 &&
              fabs(selection.user_bounds.y - 3.0) < 1e-12 &&
              fabs(selection.user_bounds.width - 4.0) < 1e-12,
              "bounds query returns user and device bounds") &&
        check(svg_shape_element_at_offset(&document,
                  (size_t)(strstr(source, "href=\"#r\"") - source),
                  &selection) && selection.source_offset == (size_t)(use - source),
              "editor byte offset resolves use host");
    svg_shape_document_destroy(&document);

    static const char stroke_source[] =
        "<svg width=\"16\" height=\"16\"><path fill=\"none\""
        " stroke=\"red\" stroke-width=\"2\" d=\"M1 5 L12 5\"/></svg>";
    if (svg_shape_decode((base_bytes){(const uint8_t *)stroke_source,
                                      sizeof(stroke_source) - 1U},
                         &document, &diagnostic) != SVG_SHAPE_ERROR_NONE)
        return false;
    okay = okay && check(svg_shape_hit_test(&document, 6.0, 5.5, 0.0,
                                             &selection),
                         "stroke-aware hit test accepts painted stroke");
    svg_shape_document_destroy(&document);
    return okay;
}

int main(void)
{
    if (!text_checks() || !text_use_symbol_checks() || !image_checks() ||
        !selection_and_path_checks())
        return 1;
    puts("text, image, selection and path-source checks passed");
    return 0;
}
use vexel_base::{Stop, WorkControl, WorkKind};
use vexel_scene::{
    ImagePixels, MediaError, MediaProvider, TableRange, TextCommand, TextGlyph, TextLayout,
    TextRequest, TextVerb,
};
use vexel_svg_media::{
    TextCache, decode_base64, decode_image, image_geometry, normalize_text, parse_data_uri,
    parse_position_list,
};
use vexel_xml::{TokenKind, XmlLimits, XmlSpan};

struct NoStop;
impl WorkControl for NoStop {
    fn charge(&mut self, _: WorkKind, _: u64) -> Result<(), Stop> {
        Ok(())
    }
    fn checkpoint(&mut self) -> Result<(), Stop> {
        Ok(())
    }
}

struct StopOnCharge;
impl WorkControl for StopOnCharge {
    fn charge(&mut self, _: WorkKind, _: u64) -> Result<(), Stop> {
        Err(Stop::Canceled)
    }
    fn checkpoint(&mut self) -> Result<(), Stop> {
        Err(Stop::Canceled)
    }
}

#[test]
fn image_data_uri_and_base64_keep_exact_grammar_and_offsets() {
    let source = b"data:image/png;base64,AQID";
    let uri = XmlSpan {
        offset: 0,
        length: source.len(),
    };
    let payload = parse_data_uri(source, uri).unwrap();
    assert_eq!(payload.mime, vexel_svg_media::ImageMime::Png);
    let mut control = NoStop;
    assert_eq!(
        decode_base64(source, payload.encoded, &mut control).unwrap(),
        [1, 2, 3]
    );
    let malformed = b"AQ!D";
    assert_eq!(
        decode_base64(
            malformed,
            XmlSpan {
                offset: 0,
                length: 4
            },
            &mut control
        )
        .unwrap_err()
        .kind,
        vexel_scene::ErrorKind::Unsupported
    );
    assert_eq!(
        parse_data_uri(
            b"https://host/x.png",
            XmlSpan {
                offset: 0,
                length: 18
            }
        )
        .unwrap_err()
        .offset,
        0
    );
    assert!(
        decode_base64(
            b"A",
            XmlSpan {
                offset: 0,
                length: 1
            },
            &mut control
        )
        .is_err()
    );
    let stopped = decode_base64(source, payload.encoded, &mut StopOnCharge).unwrap_err();
    assert_eq!(stopped.kind, vexel_scene::ErrorKind::Canceled);
    assert_eq!(stopped.offset, payload.encoded.offset);
}

#[test]
fn image_geometry_preserves_meet_slice_none_and_viewport_lengths() {
    let source = b"<image x=\"10%\" y=\"2\" width=\"4\" height=\"2\"/>";
    let (tokens, _) = vexel_xml::tokenize(source, XmlLimits::default());
    let elem = tokens
        .iter()
        .position(|t| t.kind == TokenKind::EmptyElement)
        .unwrap();
    let meet = image_geometry(
        source,
        &tokens,
        elem,
        tokens.len(),
        [100., 20.],
        Some([2, 2]),
        vexel_svg_values::Aspect::default(),
    )
    .unwrap();
    assert_eq!(
        [
            meet.x,
            meet.y,
            meet.draw_x,
            meet.draw_width,
            meet.draw_height
        ],
        [10., 2., 11., 2., 2.]
    );
    let slice = image_geometry(
        source,
        &tokens,
        elem,
        tokens.len(),
        [100., 20.],
        Some([2, 2]),
        vexel_svg_values::Aspect {
            slice: true,
            ..Default::default()
        },
    )
    .unwrap();
    assert_eq!(
        [slice.draw_x, slice.draw_width, slice.draw_height],
        [10., 4., 4.]
    );
    let none = image_geometry(
        source,
        &tokens,
        elem,
        tokens.len(),
        [100., 20.],
        Some([2, 2]),
        vexel_svg_values::Aspect {
            none: true,
            ..Default::default()
        },
    )
    .unwrap();
    assert_eq!(
        [none.draw_x, none.draw_y, none.draw_width, none.draw_height],
        [10., 2., 4., 2.]
    );
    let invalid = b"<image width=\"-1\" height=\"2\"/>";
    let (bad_tokens, _) = vexel_xml::tokenize(invalid, XmlLimits::default());
    let bad_elem = bad_tokens
        .iter()
        .position(|t| t.kind == TokenKind::EmptyElement)
        .unwrap();
    assert!(
        image_geometry(
            invalid,
            &bad_tokens,
            bad_elem,
            bad_tokens.len(),
            [8., 8.],
            None,
            Default::default()
        )
        .is_err()
    );
}

