        rgba: Vec::new(),
        byte_count: 0,
        row_stride: 0,
        width: vexel_svg_media::MAX_IMAGE_DIMENSION + 1,
        height: 1,
    };
    assert_eq!(
        oversized.validate(18).unwrap_err().kind,
        vexel_scene::ErrorKind::InvalidArgument
    );
}

